// Force-included for every recompiled source when building with GCC (devkitA64).
//
// rayman_pch.h (generated by rexglue) defines DEFINE_REX_FUNC for non-clang
// compilers with the `alias` attribute placed BEFORE `extern "C"`, which GCC
// silently ignores ("attributes may be inserted here"): `name` then never gets
// defined and the link fails with ~35000 undefined sub_XXXXXXXX. This version
// puts the attribute after the declarator, which GCC honours.
#pragma once

#define DEFINE_REX_FUNC(name)                                                                 \
  extern "C" void __imp__##name(PPCContext& __restrict, uint8_t*);                           \
  extern "C" void name(PPCContext& __restrict, uint8_t*)                                     \
      __attribute__((alias("__imp__" #name), weak, noinline));                               \
  extern "C" void __imp__##name([[maybe_unused]] PPCContext& __restrict ctx, uint8_t* base)
